import { expect, test } from "@playwright/test"
import { ORGANIZER } from "./support/accounts"
import { openEventList, signIn } from "./support/auth"

test("seeded application row before and after the compact layout", async ({ page }) => {
  const participant = "Jana Nováková"
  await signIn(page, "organizer", ORGANIZER)
  await openEventList(page)
  const event = page.getByRole("link", { name: /Letní kemp 2027(?! – demo)/ })
  const eventPath = await event.getAttribute("href")
  expect(eventPath).toMatch(/^\/organizer\/events\/[^/]+$/)
  await page.goto(`${eventPath}/applications?q=${encodeURIComponent(participant)}`)

  await expect(page.getByRole("heading", { name: "Applications", exact: true })).toBeVisible()
  await expect(page.getByText(participant, { exact: true }).filter({ visible: true })).toBeVisible()
  await expect(page.getByText("Confirmed", { exact: true }).filter({ visible: true }).first()).toBeVisible()
  if (process.env.SHOT_PHASE === "after") {
    await expect(page.getByRole("button", { name: participant, exact: true })).toHaveAttribute(
      "aria-expanded",
      "false",
    )
  } else {
    await expect(page.getByText("ucastnik@example.com", { exact: false }).filter({ visible: true })).toBeVisible()
  }
  const mobile = page.viewportSize()!.width === 360
  const row = page.getByRole(mobile ? "listitem" : "row").filter({ hasText: participant }).filter({ visible: true })
  await expect(row).toHaveCount(1)
  await page.waitForLoadState("networkidle")
  await page.evaluate(() => document.fonts.ready)
  const rect = await row.boundingBox()
  console.log("ROW_METRICS", process.env.SHOT_PHASE, mobile ? 360 : 1280, rect!.height)
  await row.screenshot({path:process.env.SHOT_PATH!.replace(".png","-row.png"), animations:"disabled"})
  await page.screenshot({ path: process.env.SHOT_PATH!, fullPage: true })
  if (process.env.SHOT_PHASE === "after") {
    const trigger = row.getByRole("button", { name: participant, exact: true })
    if (mobile) await trigger.tap()
    else await trigger.press("Enter")
    await expect(row.getByText(/^Received ·/)).toBeVisible()
    await row.screenshot({path:process.env.SHOT_PATH!.replace(".png","-open.png"),animations:"disabled"})
  }
})
